#include <iostream>
#include <vector>
#include <map>
#include <cassert>
#include <cstdint>
using namespace std;

const int MOD = 1000000007;

class ModInt {
public:
    int v;

    ModInt(long long val = 0) {
        val %= MOD;
        if (val < 0) val += MOD;
        v = static_cast<int>(val);
    }

    static int mod_inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return v; }

    ModInt& operator+=(const ModInt& o) {
        v += o.v;
        if (v >= MOD) v -= MOD;
        return *this;
    }

    ModInt& operator-=(const ModInt& o) {
        v -= o.v;
        if (v < 0) v += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return static_cast<unsigned>(x % m);
    }

    ModInt& operator*=(const ModInt& o) {
        v = fast_mod(static_cast<uint64_t>(v) * o.v);
        return *this;
    }

    ModInt& operator/=(const ModInt& o) {
        return *this *= o.mod_inverse();
    }

    friend ModInt operator+(const ModInt& a, const ModInt& b) { return ModInt(a) += b; }
    friend ModInt operator-(const ModInt& a, const ModInt& b) { return ModInt(a) -= b; }
    friend ModInt operator*(const ModInt& a, const ModInt& b) { return ModInt(a) *= b; }
    friend ModInt operator/(const ModInt& a, const ModInt& b) { return ModInt(a) /= b; }

    ModInt& operator++() {
        v = (v == MOD - 1) ? 0 : v + 1;
        return *this;
    }

    ModInt& operator--() {
        v = (v == 0) ? MOD - 1 : v - 1;
        return *this;
    }

    ModInt operator++(int) { ModInt tmp = *this; ++*this; return tmp; }
    ModInt operator--(int) { ModInt tmp = *this; --*this; return tmp; }

    ModInt operator-() const { return v ? MOD - v : 0; }

    bool operator==(const ModInt& o) const { return v == o.v; }
    bool operator!=(const ModInt& o) const { return v != o.v; }

    ModInt mod_inverse() const { return ModInt::mod_inverse(v); }

    ModInt pow(long long e) const {
        assert(e >= 0);
        ModInt b = *this, res = 1;
        while (e > 0) {
            if (e & 1) res *= b;
            b *= b;
            e >>= 1;
        }
        return res;
    }
};

const int MAX_N = 7;
int N;
ModInt prob[MAX_N][MAX_N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = ModInt(p) / ModInt(100);
        }
    }

    vector<vector<int>> masks_by_pop(MAX_N + 1);
    vector<int> pos_map(1 << N, -1);

    for (int mask = 0; mask < (1 << N); ++mask) {
        int pop = __builtin_popcount(mask);
        pos_map[mask] = masks_by_pop[pop].size();
        masks_by_pop[pop].push_back(mask);
    }

    map<long long, ModInt> dp;
    dp[1LL << pos_map[0]] = ModInt(1);

    for (int iter = 0; iter < N; ++iter) {
        map<long long, ModInt> ndp;

        for (int cur = 0; cur < (1 << N); ++cur) {
            ModInt prod = ModInt(1);
            for (int j = 0; j < N; ++j) {
                if ((cur >> j) & 1) {
                    prod *= prob[iter][j];
                } else {
                    prod *= (ModInt(1) - prob[iter][j]);
                }
            }

            for (const auto& [state, p] : dp) {
                long long cur_state = state;
                ModInt cur_p = p;

                long long next_state = 0;

                for (int mask : masks_by_pop[iter]) {
                    if ((cur_state >> pos_map[mask]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((cur >> i) & 1) && !((mask >> i) & 1)) {
                                next_state |= 1LL << pos_map[mask | (1 << i)];
                            }
                        }
                    }
                }

                ndp[next_state] += cur_p * prod;
            }
        }

        dp = move(ndp);
    }

    ModInt ans = ModInt(0);
    long long full = (1LL << N) - 1;

    for (const auto& [state, p] : dp) {
        if ((state >> pos_map[full]) & 1) {
            ans += p;
        }
    }

    cout << (int)ans << '\n';
    return 0;
}
